import json,re,sys
sys.path.insert(0,'tools')
from b652_record import conv
j=json.load(open('data/b676_q0_lines.json',encoding='utf-8'))
h=[x for x in j['hits'] if x['reading']=='TO RE-CUT']
for x in h:
  s=x['s']; c=conv(s)
  hz=[]
  if c.count('\`')%2: hz.append('odd-tick')
  if '|' in s: hz.append('pipe')
  if 'None' in s or ' ? ' in s or '### NOT' in s: hz.append('unread')
  if re.search(r'\b(gap|blind)',s,re.I): hz.append('stem')
  if '\n' in s: hz.append('newline')
  if hz: print(x['file'][:4],x['line'],hz, s[:90].replace('\n',' '))
"

